def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda x: sum(v == x for row in grid for v in row))
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            comps.append((color, cells))

    # Find the long L-shaped color marker.
    marker = None
    best = -1
    for color, cells in comps:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        height, width = r1-r0+1, c1-c0+1
        if height < 4 or width < 4:
            continue
        # A marker is the union of a full bounding-box edge row and edge column.
        for corner in ((r0,c0),(r0,c1),(r1,c0),(r1,c1)):
            cr, cc = corner
            edge_row = {(cr, x) for x in range(c0,c1+1)}
            edge_col = {(y, cc) for y in range(r0,r1+1)}
            if edge_row | edge_col == set(cells) and len(cells) > best:
                marker, best = color, len(cells)

    if marker is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    # Recolor isolated three-cell L triominoes.
    for color, cells in comps:
        if len(cells) != 3:
            continue
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        if max(rs)-min(rs) == 1 and max(cs)-min(cs) == 1:
            for r, c in cells:
                out[r][c] = marker
    return out
